import pandas as pd
import pickle
import os

# Get the absolute path to the current directory to find the .pkl files
BASE_DIR = os.path.dirname(os.path.abspath(__file__))

def get_recommendations(game_title, num_recommendations=3):
    try:
        # Load the files generated by train_model.py
        with open(os.path.join(BASE_DIR, '../games_metadata.pkl'), 'rb') as f:
            games_df = pickle.load(f)
        with open(os.path.join(BASE_DIR, '../similarity_matrix.pkl'), 'rb') as f:
            cosine_sim = pickle.load(f)

        # Check if game exists in our data
        if game_title not in games_df['title'].values:
            return []

        # Get index of the game
        idx = games_df[games_df['title'] == game_title].index[0]

        # Get similarity scores
        sim_scores = list(enumerate(cosine_sim[idx]))
        sim_scores = sorted(sim_scores, key=lambda x: x[1], reverse=True)

        # Get top matches (excluding the game itself)
        sim_scores = sim_scores[1:num_recommendations+1]
        game_indices = [i[0] for i in sim_scores]

        return games_df['title'].iloc[game_indices].tolist()
    except Exception as e:
        print(f"Error in ML engine: {e}")
        return []